model Plan {
  id           String        @id @default(cuid())
  slug         String        @unique
  name         String
  cpuCores     Int
  ramMB        Int
  diskGB       Int
  bandwidthTB  Float         @default(1)
  priceCents   Int
  storageTier  String        @default("nvme") // "nvme" | "hdd"
  active       Boolean       @default(true)
  sortOrder    Int           @default(0)
  createdAt    DateTime      @default(now())
  servers      Server[]
  gamePlans    GamePlan[]
  // NxCloud tiers that clone/size their VM from this Plan. A backing Plan for an
  // NxCloud tier is kept `active = false` so it never shows in the VPS wizard.
  nxcloudPlans NxCloudPlan[]
}

enum ImageCategory {
  PLAIN_OS
  CONTROL_PANEL
  APPLICATION
}

/// An installable image shown in the deploy wizard. Plain OS clones `baseVmid`
/// directly; control panels / apps clone `baseVmid` then run `setupScript`
/// (cloud-init runcmd) to install the panel/app on first boot.
model OsTemplate {
  id              String        @id @default(cuid())
  slug            String        @unique
  name            String // display name, e.g. "Ubuntu"
  category        ImageCategory @default(PLAIN_OS)
  family          String        @default("linux") // ubuntu | debian | almalinux | rocky | cpanel | ...
  version         String        @default("") // "24.04", "13", ""
  logo            String        @default("") // icon slug for the UI
  vmid            Int // legacy/base template VMID to clone
  baseVmid        Int? // explicit base OS template for panels/apps (falls back to vmid)
  setupScript     String? // shell installed via cloud-init runcmd (panels/apps)
  minRamMB        Int           @default(1024)
  minDiskGB       Int           @default(10)
  licenseRequired Boolean       @default(false) // e.g. cPanel/Plesk need a paid license
  featured        Boolean       @default(false)
  sortOrder       Int           @default(0)
  active          Boolean       @default(true)
  servers         Server[]
}

/// Backup frequency & retention tier sold as a recurring add-on (lib/backup-tiers.ts).
/// MVP sells FREE (included, keep 2) and PLUS (paid, keep 7); PRO/PREMIUM are
/// defined for forward-compatibility but not offered in the funnel yet.
enum BackupTier {
  FREE
  PLUS
  PRO
  PREMIUM
}

model Server {
  id                  String           @id @default(cuid())
  name                String
  label               String? // customer-facing nickname (rename)
  hostname            String
  vmid                Int?             @unique
  status              ServerStatus     @default(PENDING)
  ipAddress           String?          @unique
  sshPort             Int?             @unique
  rootPassword        String?
  rootPasswordEnc     String?
  isFree              Boolean          @default(false)
  autoRenew           Boolean          @default(true)
  gameVariant         String? // game-server type/loader (e.g. paper, carbon, bepinex) — see lib/game-config
  gameConfig          Json? // per-game settings values (validated against the family schema)
  suspendedNote       String?
  // WHY a server is suspended: "UNPAID" | "ABUSE" | "ADMIN". Null = never suspended.
  //
  // `suspendedNote` used to be the only signal, and nothing consumed it, so every
  // suspension looked identical to the billing engine. Two live consequences:
  // (1) `terminateOverdue` selected on `status: "SUSPENDED"` alone, while the
  //     renewal sweep EXCLUDES suspended servers — so an admin suspending a
  //     paid-up customer pending an investigation meant they were never charged,
  //     never warned, their term lapsed, and 13 days later their VM and all its
  //     data were destroyed with a "prolonged non-payment" notice they had never
  //     been given a chance to act on.
  // (2) `renewNow` auto-unsuspended ANY suspended server on payment, so a spammer
  //     suspended for outbound abuse could pay and put themselves straight back
  //     on the network.
  // Both now scope strictly to UNPAID.
  suspendReason       String?
  // Human-readable reason a PROVISION failed terminally, set by the worker on the
  // ERROR path (worker/index.ts). Surfaced on the server detail page's ERROR
  // banner so the customer sees WHAT went wrong instead of a bare red status dot.
  // Cleared when a retry re-enqueues provisioning. Null = never failed (or the
  // failure predates this column).
  provisionError      String?
  expiresAt           DateTime?
  // ---- Dunning (failed auto-charge retry state) ----
  // dunningStage counts CARD ATTEMPTS THAT HAVE FAILED for the current unpaid
  // period: 0 = nothing owed / paid, 1..N = that many failures. Reset to 0 the
  // moment a renewal succeeds. `dunningNextAt` gates the next retry so a
  // 5-minute billing sweep cannot burn every retry in a quarter of an hour, and
  // `dunningPayUrl` is a hosted Checkout link emailed to the customer so they can
  // clear the balance themselves (also how 3-D Secure challenges are satisfied).
  dunningStage        Int              @default(0)
  dunningNextAt       DateTime?
  dunningPayUrl       String?
  createdAt           DateTime         @default(now())
  updatedAt           DateTime         @updatedAt
  userId              String
  user                User             @relation(fields: [userId], references: [id])
  nodeId              String?
  node                Node?            @relation(fields: [nodeId], references: [id])
  bwInBytes           BigInt           @default(0)
  bwOutBytes          BigInt           @default(0)
  abuseBwMark         BigInt? // last bwOutBytes sample, for outbound-rate abuse detection
  abuseBwMarkAt       DateTime? // when abuseBwMark was taken
  bwWindowStart       DateTime         @default(now())
  termMonths          Int              @default(1) // 1=monthly, 12=annual, 24=biennial, 36=triennial
  /// PERCENT OFF the term-discounted monthly rate that the months currently sitting
  /// between `now` and `expiresAt` were ACTUALLY sold at. This is the rate basis
  /// every proration must price against (lib/proration.ts).
  ///
  /// WHY IT EXISTS (2026-07-26). `prorateDeltaCents` defaulted its rate basis to
  /// `currentPromo(now)` — whatever seasonal promo happened to be running at the
  /// instant a resize was priced. Promos rotate by calendar date from a 15% Launch
  /// Sale to 45% for Cyber Monday, so a customer could upgrade during Cyber Monday
  /// (delta priced at 55% of the honest rate, small charge) and downgrade during
  /// the Launch Sale (delta priced at 85%, large credit) and pocket the 30-point
  /// spread x plan delta x every remaining month — repeatable every promo cycle,
  /// self-service, with the platform's own marketing calendar as the schedule.
  /// lib/promotions.ts is explicit that a promo is a FIRST-TERM intro discount that
  /// renewals never receive, so pricing a mid-term change off today's promo was
  /// wrong even before it was exploitable.
  ///
  /// WHY A PERCENT AND NOT A CENTS RATE. Proration is a DIFFERENCE between two
  /// plans' rates. A stored $/mo figure prices only the plan the server is on and
  /// says nothing about the plan it is moving to, so the other half of the
  /// subtraction would still need a basis invented for it — which is the bug. A
  /// percent is a rate BASIS that applies to any plan price, so both halves of the
  /// delta come from this one persisted number and the round trip is symmetric by
  /// construction rather than by convention. It also survives a plan change with no
  /// write at all: the customer keeps the rate they bought at, so up-then-down is
  /// exactly zero.
  ///
  ///   0   = full price. What BOTH renewal paths bill (worker/billing.ts sweep and
  ///         lib/actions.ts renewNow charge `vpsTermPriceCents` with no promo), and
  ///         what a flat-priced game plan is sold at.
  ///   1-99= a genuine intro/seasonal discount, or a blend of paid and gifted
  ///         months (see prorateBlendPercent in lib/proration.ts).
  ///   100 = gifted. Nothing was paid for these months, so nothing may prorate out
  ///         of them — an admin extension/free grant records this.
  ///   NULL= unknown. Only on rows that predate this column; resolved by an
  ///         EXPLICIT conservative fallback (`resolveTermPromoPercent`), never by
  ///         falling through to today's promo, because that IS the bug above.
  ///
  /// FLOAT, not Int, even though every promo in the catalogue is a whole number.
  /// Blending a renewal into a part-used term lands on halves: 36 months at 45% off
  /// plus 36 renewed at full price is exactly 22.5% off, and rounding that to 23
  /// quietly shaves $7.20 off a $1,071.36 credit. A first term still stores the
  /// promo's exact integer, so the column reads the same for the common case.
  termPromoPercent    Float?
  /// PERCENT the ANNUAL (12-month) commitment discount was set to when THIS server's
  /// term was sold — a snapshot of `annual_discount_percent` (lib/annual-discount.ts)
  /// frozen at the moment of sale, exactly like `termPromoPercent` freezes the seasonal
  /// rate.
  ///
  /// WHY IT EXISTS. The annual discount became an admin-configurable setting, read LIVE
  /// by proration (lib/proration.ts, via `vpsEffectiveMonthly`). Both halves of a resize
  /// round trip therefore priced against whatever the setting held at the instant each
  /// half ran: an admin nudging `annual_discount_percent` between a customer's upgrade
  /// and their downgrade made the credit and the charge disagree, so an annual server's
  /// up-then-down no longer netted to zero. Freezing the rate the server was SOLD at and
  /// reading THAT from both proration directions makes the round trip symmetric by
  /// construction, the same way `termPromoPercent` does for the promo rate.
  ///
  ///   NULL = pre-existing row (predates this column) OR a non-annual/flat-priced server
  ///          that never had an annual discount. Proration falls back to the LIVE setting
  ///          for these — identical maths for every non-annual term, and the best
  ///          available basis for a legacy annual row.
  annualDiscountPct   Float?
  /// The PLAN-portion cash actually collected for this term at the moment of sale,
  /// in cents, NET of promo AND coupon and EXCLUDING recurring add-ons (dedicated IP,
  /// extra disk, paid backups). This is the authoritative basis for a cancellation
  /// refund: `terminationRefundCents` prorates THIS over the unused months rather than
  /// recomputing from list price × `termPromoPercent` — which lies (currentPromo stamps
  /// 100 even on a full-price VPS, zeroing the refund) and is coupon-blind (a coupon
  /// reduces cash collected but never `termPromoPercent`, so the old basis over-refunded
  /// the coupon amount). Storing the real cash makes the refund exact and provably
  /// ≤ paid. NULL = row predates this column → refund falls back to the conservative
  /// `termPromoPercent` formula (never over-refunds; $0 for the 100-stamped common case).
  /// Left at its first-term value across renewals (renewals charge FULL price, so the
  /// stored first-term net is ≤ what any later term collected → still never over-refunds).
  refundableTermCents Int?
  /// GB of root disk purchased BEYOND the plan's `diskGB`. The server's EFFECTIVE

/**
 * Promotional pricing — the SINGLE "first month free" offer.
 *
 * SCOPE: this promo is granted on SHARED WEB HOSTING ONLY (owner decision,
 * 2026-08-11). The grant is gated by lib/promo-redemption.ts
 * `firstMonthFreeAppliesTo` — VPS / Email / Game always bill full. This module
 * only models the offer's shape (100%-off-first-term); it does NOT decide which
 * products get it. Marketing surfaces must read the redemption gate, not assume
 * sitewide.
 *
 * There is exactly one promo now (owner decision, 2026-08-11): the customer's
 * FIRST TERM is free, then the plan renews at its regular price. This replaced
 * three contradictory mechanics that used to run at once — a rotating 15–45%
 * intro discount, a fictional "20% off 3-year annual billing" band, and a
 * homepage annual toggle — which produced three different live prices for the
 * same plan and contradicted the homepage pledge that the sign-up price is the
 * renewal price. Under first-month-free that pledge is finally TRUE: you sign up
 * free and then renew at exactly the price shown ($X/mo).
 *
 * It is modelled as a 100%-off-first-term discount so every existing call site
 * keeps working untouched:
 *   - promoPriceCents(regular) => 0            (the first-term charge is $0)
 *   - currentPromo(now).discountPercent === 100
 * The "regular" (strikethrough) price is the genuine renewal price. Renewal
 * paths (worker/billing.ts, worker/product-renewals.ts, lib/renewal-charge.ts)
 * bill plan.priceCents unchanged — never the promo price — so displayed ===
 * charged both at sign-up ($0) and at renewal ($X).
 *
 * Add-ons (dedicated IP, extra disk) are billed at full price at order time;
 * the promo only touches the plan portion (see lib/order.ts).
 *
 * Pure & deterministic: every helper takes `now` as a parameter (kept for API
 * compatibility even though the single promo is always-on). Nothing here calls
 * Date.now() at module load, so it is safe to import anywhere.
 */

export type Promo = {
  id: string;
  /** Full name, e.g. "First month free". */
  name: string;
  /** Short badge text. */
  label: string;
  /** Percent off the FIRST-term charge (0–100). 100 = first term free. */
  discountPercent: number;
  /** True for the first-month-free offer (granted on Shared Hosting only). */
  firstMonthFree: boolean;
};

/**
 * The one and only promo: always on, first term free, then renews at the
 * regular price. No countdown, no rotation — nothing to expire, so nothing to
 * fake a timer on.
 */
export const FIRST_MONTH_FREE: Promo = {
  id: "first-month-free",
  name: "First month free",
  label: "First month free",
  discountPercent: 100,
  firstMonthFree: true,
};

/**
 * The active promo for `now`. There is only one, and it is always on, so this
 * always returns it. (Kept taking `now` for call-site compatibility.)
 */
export function currentPromo(_now: Date): Promo {
  return FIRST_MONTH_FREE;
}

/**
 * The one discount formula: round(regularCents * (1 - discountPercent/100)).
 *
 * Split out from `promoPriceCents` so proration can price against the percent a
 * server's term was ACTUALLY sold at (Server.termPromoPercent) without inventing
 * a fake `Promo` object to carry the number — and, crucially, without a second
 * copy of this line. Checkout and proration must round identically or an upgrade
 * and its mirror-image downgrade stop cancelling.
 */
export function discountedCents(regularCents: number, discountPercent: number): number {
  return Math.round(regularCents * (1 - discountPercent / 100));
}

/**
 * The genuine first-term price for a regular price under `promo`. This exact
 * value is what checkout charges for the first term — display it verbatim. Under
 * first-month-free (100% off) this is $0.
 */
export function promoPriceCents(regularCents: number, promo: Promo): number {
  return discountedCents(regularCents, promo.discountPercent);
}

/**
 * The DEEPEST discount this platform has ever run. With a single 100%-off promo
 * this is 100.
 *
 * Used as the conservative fallback rate for a server whose sold rate is
 * genuinely unrecoverable (lib/proration.ts `resolveTermPromoPercent`). "Assume
 * they paid the least we have ever charged" keeps a prorated CREDIT below the
 * cash actually collected. Proration prices a DELTA, so at 100% both the upgrade
 * charge and the downgrade credit collapse to zero — a revenue concession on an
 * unknown-rate row, never a payout.
 */
export function deepestPromoPercent(): number {
  return FIRST_MONTH_FREE.discountPercent;
}

/**
 * Kept for API compatibility. The single promo is always-on and has no honest
 * close date, so callers no longer render a countdown; this returns `now` for
 * any straggler that still expects a Date.
 */
export function promoEndsAt(now: Date, _promo: Promo): Date {
  return now;
}

/**
 * Billing term definitions + discount math, shared by ordering, renewal,
 * the deploy wizard, invoices and the domain flow. Discounts are the platform's
 * promo (longer commitment = cheaper); tune here (or later via admin Settings).
 */

export type VpsTerm = { months: number; label: string; short: string; discountPct: number };

/** The ANNUAL term is 12 months — the one term whose discount is admin-configurable. */
export const ANNUAL_TERM_MONTHS = 12;

/**
 * The annual (12-month) commitment discount SHIPPED as the default, and the fallback
 * for the `annual_discount_percent` admin setting (lib/annual-discount.ts).
 *
 * It MUST equal the 12-month `VPS_TERMS` discountPct below: a platform whose
 * `Setting` table has no `annual_discount_percent` row must price the annual term
 * EXACTLY as it did before the setting existed, so no existing annual server's
 * renewal price moves the moment this wiring lands. The setting only ever raises or
 * lowers it deliberately, from the admin Billing panel.
 */
export const DEFAULT_ANNUAL_DISCOUNT_PCT = 20;

export const VPS_TERMS: VpsTerm[] = [
  { months: 1, label: "Monthly", short: "1 mo", discountPct: 0 },
  // Annual is admin-configurable — this is only the SHIPPED default. Every charge
  // path resolves the live rate via `annualDiscountPct()` and passes it through
  // `vpsTermPriceCents`; this constant is what an un-wired caller (and a 2-arg call)
  // falls back to. Keep it === DEFAULT_ANNUAL_DISCOUNT_PCT.
  { months: 12, label: "Annual", short: "1 yr", discountPct: DEFAULT_ANNUAL_DISCOUNT_PCT },
  // Biennial/Triennial are FIXED platform rates (NOT admin-configurable), so for these
  // terms the order and every renewal read the SAME constant here → displayed ===
  // charged === renewed by construction, with no per-account freezing needed. Editing a
  // rate here only reprices NEW orders; any existing longer-term account simply renews
  // at the new (always-cheaper) rate — never an overcharge.
  { months: 24, label: "Biennial", short: "2 yr", discountPct: 30 },
  { months: 36, label: "Triennial", short: "3 yr", discountPct: 40 },
];

export function vpsTerm(months: number): VpsTerm {
  return VPS_TERMS.find((t) => t.months === months) ?? VPS_TERMS[0];
}

/**
 * The discount percent to apply to a term.
 *
 * For the ANNUAL (12-month) term this is admin-configurable: pass the
 * `annualDiscountPct` resolved from the `annual_discount_percent` setting
 * (lib/annual-discount.ts) and it WINS over the shipped default. Every other term
 * keeps its fixed `VPS_TERMS` rate. Omitting the override — or passing a
 * non-finite value — falls back to the shipped default, so a 2-arg
 * `vpsTermPriceCents` call and any caller that has not been wired up price annual at
 * `DEFAULT_ANNUAL_DISCOUNT_PCT`, i.e. exactly what the platform shipped before.
 * Clamped to 0..90 here as a second line of defence behind the setting reader.
 */
export function termDiscountPct(months: number, annualDiscountPct?: number): number {
  if (months === ANNUAL_TERM_MONTHS && annualDiscountPct != null && Number.isFinite(annualDiscountPct)) {
    return Math.min(90, Math.max(0, annualDiscountPct));
  }
  return vpsTerm(months).discountPct;
}

/**
 * Total charge (cents) for a plan over a term, discount applied.
 *
 * `annualDiscountPct` (optional) overrides the ANNUAL term's discount with the
 * admin-configured rate; see `termDiscountPct`. It is the ONE knob that makes
 * annual billing configurable while keeping this the single price formula —
 * displayed (deploy wizard), charged (lib/order.ts) and renewed (renewalCharge)
 * all call this with the SAME resolved rate, so they cannot disagree.
 */
export function vpsTermPriceCents(monthlyCents: number, months: number, annualDiscountPct?: number): number {
  const pct = termDiscountPct(months, annualDiscountPct);
  return Math.round(monthlyCents * months * (1 - pct / 100));
}

/**
 * Generic term price — the product-agnostic name for the ONE term formula above.
 * Shared Hosting, Business Email, Game servers and NxCloud all price a term as
 * `monthlyCents × months × (1 − annualDiscount)` exactly the way a VPS does, so
 * they call THIS and there is a single arithmetic for every product+term. It is a
 * thin alias of `vpsTermPriceCents` on purpose: the annual discount is resolved
 * once (order) and re-resolved (renewal) against the SAME setting, so
 * displayed === charged === renewed holds for every product.
 */
export function termPriceCents(monthlyCents: number, months: number, annualDiscountPct?: number): number {
  return vpsTermPriceCents(monthlyCents, months, annualDiscountPct);
}

/**
 * The terms offered on the NON-VPS products (Shared Hosting, Business Email, Game
 * servers, NxCloud): the full ladder — Monthly, Annual (admin-configurable),
 * Biennial and Triennial — the SAME set VPS sells. Every product prices a term
 * through the one `termPriceCents` formula, so the longer-commitment discounts
 * (20 / 30 / 40%) apply uniformly across the platform.
 */
export const PRODUCT_TERMS: VpsTerm[] = [...VPS_TERMS];

/**
 * Clamp any term input from a product order form to a SUPPORTED product term —
 * one of the `PRODUCT_TERMS` months (1 / 12 / 24 / 36). A malformed / unlisted
 * value can therefore only ever fall back to the cheapest (monthly) term, never
 * grant a longer paid term the customer did not pay for. The order path then prices
 * whatever term this returns through `termPriceCents`, so the charge always matches
 * the term granted.
 */
export function normalizeProductTerm(months: unknown): number {
  const m = Math.round(Number(months));
  return PRODUCT_TERMS.some((t) => t.months === m) ? m : 1;
}

/**
 * Effective monthly-equivalent price after the term discount (for "$/mo" display).
 *
 * `months <= 0` returns the undiscounted monthly price rather than dividing by it.
 * This is not display hygiene — it is a money guard. `prorateDeltaCents`
 * (lib/proration.ts) prices BOTH halves of every upgrade and downgrade credit
 * through this function using `Server.termMonths`, and a 0 there made the division
 * `0 / 0` → NaN, which sails through `Math.round`, through `Math.max(0, delta)`
 * (NaN is not > 0, so the clamp returns NaN, not 0) and into `debitWallet` as the
 * amount to take. The result is a charge that either explodes at the database or,
 * on the credit side, writes NaN where a customer's balance used to be. The column
 * defaults to 1 and every writer clamps to >= 1 today, so this is a latch, not a
 * live bug — but a shared money function must not have a NaN in it.
 */
export function vpsEffectiveMonthly(monthlyCents: number, months: number, annualDiscountPct?: number): number {
  if (!Number.isFinite(months) || months <= 0) return Math.round(monthlyCents);
  return Math.round(vpsTermPriceCents(monthlyCents, months, annualDiscountPct) / months);
}

export type DomainTerm = { years: number; label: string; discountPct: number };

export const DOMAIN_TERMS: DomainTerm[] = [
  { years: 1, label: "1 year", discountPct: 0 },
  { years: 2, label: "2 years", discountPct: 5 },
  { years: 3, label: "3 years", discountPct: 10 },
];

export function domainTerm(years: number): DomainTerm {
  return DOMAIN_TERMS.find((t) => t.years === years) ?? DOMAIN_TERMS[0];
}

/** Total charge (cents) for a domain over N years, discount applied. */
export function domainTermPriceCents(perYearCents: number, years: number): number {
  const t = domainTerm(years);
  return Math.round(perYearCents * years * (1 - t.discountPct / 100));
}

/** Add whole months to a date (UTC-safe enough for billing windows). */
export function addMonths(from: Date, months: number): Date {
  const d = new Date(from);
  d.setMonth(d.getMonth() + months);
  return d;
}

