147	export function orderPriceOf(
148	  quote: {
149	    chargeCents: number;
150	    promo: { discountPercent: number; name: string };
151	  },
152	  tax?: { taxCents: number; ratePercent: number; country: string } | null,
153	): OrderPrice {
154	  return {
155	    chargeCents: quote.chargeCents,
156	    promoPercent: quote.promo.discountPercent,
157	    promoName: quote.promo.name,
158	    ...(tax
159	      ? { taxCents: tax.taxCents, taxRatePercent: tax.ratePercent, taxCountry: tax.country }
