164	/**
165	 * Parse a sold price back off Stripe metadata. Returns null unless EVERY field is
166	 * well-formed: a half-parsed price would be worse than no price at all, because
167	 * the caller's fallback (re-quote) is at least internally consistent.
168	 */
169	export function parseOrderPrice(raw: unknown): OrderPrice | null {
170	  let obj: unknown = raw;
171	  if (typeof raw === "string") {
172	    try {
173	      obj = JSON.parse(raw);
174	    } catch {
175	      return null;
176	    }
177	  }
178	  if (!obj || typeof obj !== "object") return null;
179	  const { chargeCents, promoPercent, promoName, taxCents, taxRatePercent, taxCountry } =
180	    obj as Record<string, unknown>;
181	  if (typeof chargeCents !== "number" || !Number.isInteger(chargeCents) || chargeCents < 0) return null;
182	  if (typeof promoPercent !== "number" || !Number.isInteger(promoPercent)) return null;
183	  if (promoPercent < 0 || promoPercent > 100) return null;
184	  // Tax fields are ADDITIVE and lenient: a session written before Finding 1 (or with a
185	  // malformed tax field) carries none, and the charge path recomputes tax from the
186	  // owner's country — which undertaxes at worst, never overcharges.
187	  const tc = typeof taxCents === "number" && Number.isInteger(taxCents) && taxCents >= 0 ? taxCents : 0;
188	  const tr =
189	    typeof taxRatePercent === "number" && Number.isFinite(taxRatePercent) && taxRatePercent >= 0
190	      ? taxRatePercent
191	      : 0;
192	  return {
193	    chargeCents,
194	    promoPercent,
195	    promoName: typeof promoName === "string" ? promoName : "",
196	    taxCents: tc,
197	    taxRatePercent: tr,
198	    taxCountry: typeof taxCountry === "string" ? taxCountry : "",
199	  };
200	}
