231	/**
232	 * Pick the least-committed enabled node (RAM headroom), while steering AWAY from
233	 * a node this order would push to/past the CRITICAL capacity threshold when
234	 * another node has room. Falls back to primary (any node) when every candidate is
235	 * already critical — the scheduler never REFUSES an order for a capacity warning
236	 * (that's the node-capacity alert's job, lib/node-capacity.ts); it only prefers a
237	 * roomier node when one exists. DB-only so order placement never blocks on a
238	 * Proxmox round trip.
239	 */
240	async function scheduleNode(planRamMB: number) {
241	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
242	  if (nodes.length === 0) return null;
243	  const loads = await Promise.all(
244	    nodes.map(async (n) => {
245	      const agg = await db.server.findMany({
246	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
247	        select: { plan: { select: { ramMB: true } } },
248	      });
249	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
250	      // Commitment AFTER this VM lands — that's what decides whether placing here
251	      // tips the node critical.
252	      const projectedPct = n.capacityRamMB > 0 ? ((used + planRamMB) / n.capacityRamMB) * 100 : 100;
253	      return { node: n, free: n.capacityRamMB - used, projectedPct };
254	    }),
255	  );
256	  const { critPct } = await nodeThresholds();
257	  const roomy = loads.filter((l) => l.projectedPct < critPct);
258	  const pool = roomy.length > 0 ? roomy : loads;
259	  pool.sort((a, b) => b.free - a.free);
260	  return pool[0].node;
261	}
