263	/** Validate + price an order without placing it. Throws OrderError on any problem. */
264	export async function orderQuote(intent: OrderIntent, opts?: { suppressPromo?: boolean }) {
265	  const parsed = orderSchema.safeParse(intent);
266	  if (!parsed.success) throw new OrderError(parsed.error.issues[0]?.message ?? "Invalid input.");
267	  const plan = await db.plan.findUnique({ where: { id: intent.planId } });
268	  const os = await db.osTemplate.findUnique({ where: { id: intent.osTemplateId } });
269	  if (!plan?.active || !os?.active) throw new OrderError("Plan or OS not available.");
270	  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
271	    throw new OrderError(
272	      `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
273	    );
274	  }
275	  const term = vpsTerm(Number(intent.termMonths ?? 1));
276	  // The admin-configured ANNUAL discount, resolved ONCE here and passed to
277	  // `vpsTermPriceCents` so the annual term is charged at the same rate the deploy
278	  // wizard displayed and every renewal will bill. Ignored for non-annual terms.
279	  const annualPct = await annualDiscountPct();
280	  const ipCents = intent.dedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0;
281	
282	  // Extra root disk, priced per GB/month and multiplied over the term exactly
283	  // like the dedicated-IP add-on (and, like it, NOT discounted by the term or the
284	  // promo — the customer pays the same $/GB whichever term they pick, and renews
285	  // at the same rate). Growth is one-way: this is permanent for the server.
286	  const extraDiskGB = normalizeExtraDiskGB(intent.extraDiskGB);
287	  const extraDiskPerGb = extraDiskGB > 0 ? await extraDiskPerGbCents() : 0;
288	  const extraDiskMonthlyCents = extraDiskCentsAt(extraDiskGB, extraDiskPerGb);
289	  const extraDiskCents = extraDiskMonthlyCents * term.months;
290	  if (effectiveDiskGB(plan.diskGB, extraDiskGB) > EXTRA_DISK_MAX_TOTAL_GB) {
291	    throw new OrderError(`A server's disk tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB.`);
292	  }
293	
294	  // Paid backup RETENTION tier, priced per month and multiplied over the term
295	  // exactly like the extra-disk add-on (NOT promo-discounted — the customer pays
296	  // the same $/mo whichever term or promo, and renews at the same rate through
297	  // renewalCharge). Only PLUS is paid; FREE (the included tier) is $0.
298	  const backupTier = normalizeBackupTier(intent.backupTier);
299	  const backupMonthlyCents =
300	    backupTier === "FREE" ? 0 : backupTierMonthlyCents(backupTier, await backupPlusMonthlyCents());
301	  const backupCents = backupMonthlyCents * term.months;
302	
303	  // Seasonal promo = HONEST intro discount on the plan's FIRST-term charge only.
304	  // The regular term price (vpsTermPriceCents) is what renewals bill unchanged in
305	  // worker/billing.ts — so the strikethrough shown on the marketing pages is the
306	  // real renewal price and this discounted value is the real first-term price.
307	  // Marketing displays promoPriceCents(regular) too, so displayed === charged.
308	  // (Dedicated IP is billed at full price; the promo only touches the plan.)
309	  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months, annualPct);
310	  const promo = currentPromo(new Date());
311	  // The promo is now MANAGED: the owner can switch it off, and every claim is
312	  // capped 1/account + 1/IP (lib/promo-redemption.ts). When the toggle is off the
313	  // quote shows — and placeOrder charges — the full price, so display === charged
314	  // on the disabled path. When it is on, the quote shows the first-month-free
315	  // price and the atomic claim in placeOrder's tx is the final arbiter of whether
316	  // the credit is actually granted (a lost race there is charged full).
317	  // `suppressPromo` prices this quote at FULL price even when the promo is on —
318	  // the card path uses it to re-quote for a customer who has already redeemed
319	  // (per-account/IP), so their Stripe leg and stamped total are full, not free.
320	  // The first-month-free promo is scoped to Shared Web Hosting only — VPS always
321	  // bills full. `firstMonthFreeAppliesTo("VPS")` is false, so promoEnabled is
322	  // false here and planFirstTermCents falls through to the regular term total.
323	  const promoEnabled =
324	    firstMonthFreeAppliesTo("VPS") && !opts?.suppressPromo && (await firstMonthFreeEnabled());
325	  // First-month-free must credit exactly ONE MONTH — not zero a multi-month term.
326	  // A naive promoPriceCents(termTotal) at 100% off would give a 36-month term 3
327	  // YEARS free. So we subtract one month of the plan's rate from the term total.
328	  // For a 1-month term this lands at $0 (genuinely first month free); for a 12/24/
329	  // 36-month term the customer pays the term minus one month. Renewals bill the
330	  // full vpsTermPriceCents unchanged (worker/billing.ts) — displayed === charged.
331	  const planFirstTermCents =
332	    promoEnabled && promo.firstMonthFree
333	      ? Math.max(0, regularPlanCents - plan.priceCents)
334	      : regularPlanCents;
335	  // The one-month credit this order gets IF the atomic claim succeeds. 0 when the
336	  // promo is off. placeOrder adds it back to charge full when the claim is lost.
337	  const promoCreditCents = regularPlanCents - planFirstTermCents;
338	
339	  // Optional checkout coupon: a service-locked, term-capped discount on the PLAN
340	  // portion only (not the dedicated-IP or extra-disk add-ons). Never throws for a
341	  // bad code — an invalid coupon leaves the price at full and surfaces `couponError`
342	  // so the deploy preview can show it; the redemption itself (count + per-user +
343	  // per-IP guards) is claimed atomically in placeOrder.
344	  let couponId: string | null = null;
345	  let couponDiscountCents = 0;
346	  let couponLabel = "";
347	  let couponError = "";
348	  let couponMaxRedemptions: number | null = null;
349	  let couponFirstTimeOnly = false;
350	  const code = (intent.couponCode ?? "").trim().toUpperCase();
351	  if (code) {
352	    if (!(await getSettingBool("coupons_enabled", true))) {
353	      couponError = "Promo codes are currently disabled.";
354	    } else {
355	      const coupon = await db.coupon.findUnique({ where: { code } });
356	      if (!coupon) {
357	        couponError = "That code isn’t valid.";
358	      } else {
359	        const verdict = couponOrderDiscountCents(
360	          {
361	            kind: coupon.kind,
362	            value: coupon.value,
363	            serviceKind: coupon.serviceKind,
364	            planSlug: coupon.planSlug,
365	            maxTermMonths: coupon.maxTermMonths,
366	            active: coupon.active,
367	            expiresAt: coupon.expiresAt,
368	            maxRedemptions: coupon.maxRedemptions,
369	            timesRedeemed: coupon.timesRedeemed,
370	            minAmountCents: coupon.minAmountCents,
371	          },
372	          {
373	            serviceKind: "VPS",
374	            planSlug: plan.slug,
375	            planMonthlyCents: plan.priceCents,
376	            termMonths: term.months,
377	            planChargeCents: planFirstTermCents,
378	          },
379	          new Date(),
380	        );
381	        if (verdict.ok) {
382	          couponId = coupon.id;
383	          couponDiscountCents = verdict.discountCents;
384	          couponLabel = verdict.label;
