422	/**
423	 * Place an order: validate, charge the wallet (unless a free admin grant),
424	 * create the Server + PROVISION job. Returns the new server id. Does NOT
425	 * redirect. Callers must ensure funds exist (or pass free) — this still
426	 * enforces balance and throws OrderError("Insufficient balance.") otherwise.
427	 *
428	 * `sold` overrides the recomputed price with the one the order was actually SOLD
429	 * at — the card-paid path passes the figure stamped on the Checkout session
430	 * BEFORE the card was charged, so the confirm redirect settles the price the
431	 * customer consented to instead of re-pricing against whatever promo is running
432	 * when they get back (mirrors `chargeCents` in lib/resize.ts applyResize and
433	 * lib/disk-expand.ts applyDiskExpand). The wallet path omits it and pays the
434	 * quote, which it computed moments ago in the same request. See OrderPrice.
435	 */
436	/**
437	 * Claim a checkout coupon in ITS OWN atomic transaction, throwing OrderError on
438	 * any failure so nothing partial survives. Kept separate from the order tx so a
439	 * wallet order can surface the failure before any money moves, and a card order
440	 * (already paid) can swallow it without stranding the paid provision.
441	 *
442	 * Guards, all enforced here: first-time-only (no prior paid server), the
443	 * redemption cap (atomic conditional increment), one-per-account and one-per-IP
444	 * (the two @@unique constraints on CouponRedemption).
445	 */
446	async function claimOrderCoupon(opts: {
447	  couponId: string;
448	  maxRedemptions: number | null;
449	  firstTimeOnly: boolean;
450	  userId: string;
451	  ipHash: string | null;
452	  amountCents: number;
453	}): Promise<void> {
454	  await db.$transaction(async (tx) => {
455	    // Self-heal first: a dead hold from THIS customer's own abandoned card checkout must
456	    // not stand between them and this coupon on a fresh (wallet) order — and its global
457	    // slot is handed back here too. Guarded to expired RESERVED rows (lib/coupon-redemption.ts).
458	    await releaseExpiredCouponHoldsFor(tx, opts.couponId, opts.userId, opts.ipHash);
459	    if (opts.firstTimeOnly) {
460	      const prior = await tx.server.count({ where: { userId: opts.userId, isFree: false } });
461	      if (prior > 0) throw new OrderError("This code is for first-time customers only.");
462	    }
463	    // Atomic conditional increment — the only thing between the last free slot and
464	    // an over-redemption when two orders race for it.
465	    const claim = await tx.coupon.updateMany({
466	      where:
467	        opts.maxRedemptions === null
468	          ? { id: opts.couponId, active: true }
469	          : { id: opts.couponId, active: true, timesRedeemed: { lt: opts.maxRedemptions } },
470	      data: { timesRedeemed: { increment: 1 } },
471	    });
472	    if (claim.count !== 1) throw new OrderError("That code has just been fully claimed.");
473	    try {
474	      await tx.couponRedemption.create({
475	        data: { couponId: opts.couponId, userId: opts.userId, ipHash: opts.ipHash, amountCents: opts.amountCents, context: "order" },
476	      });
477	    } catch {
478	      // Unique violation on (coupon,user) or (coupon,ipHash): already claimed by
479	      // this person. Throwing rolls back the increment above with it.
480	      throw new OrderError("You’ve already used this code.");
481	    }
482	  });
483	}
