485	/**
486	 * Read-only mirror of `claimOrderCoupon`'s per-person guards, for the CARD path.
487	 *
488	 * The card leg discounts `cardCents` up front and only settles the redemption
489	 * AFTER the card is charged — where a failed claim is deliberately swallowed so a
490	 * paid provision is never stranded. Without this pre-check, a customer who has
491	 * already used a one-per-person code (or isn't first-time) still gets the
492	 * discounted card charge and the swallow hides it. So before we send them to
493	 * checkout we re-run first-time-only, one-per-account, one-per-IP and the cap as
494	 * plain reads; if any fails the caller re-quotes at full price. This is advisory
495	 * (a race could still lose the atomic claim at settle time — that path stays
496	 * swallowed by design), but it closes the everyday bypass.
497	 */
498	export async function orderCouponClaimable(opts: {
499	  couponId: string;
500	  firstTimeOnly: boolean;
501	  maxRedemptions: number | null;
502	  userId: string;
503	  ipHash: string | null;
504	}): Promise<{ ok: true } | { ok: false; error: string }> {
505	  if (opts.firstTimeOnly) {
506	    const prior = await db.server.count({ where: { userId: opts.userId, isFree: false } });
507	    if (prior > 0) return { ok: false, error: "This code is for first-time customers only." };
508	  }
509	  const byUser = await db.couponRedemption.findUnique({
510	    where: { couponId_userId: { couponId: opts.couponId, userId: opts.userId } },
511	  });
512	  if (byUser) return { ok: false, error: "You’ve already used this code." };
513	  if (opts.ipHash) {
514	    const byIp = await db.couponRedemption.findFirst({ where: { couponId: opts.couponId, ipHash: opts.ipHash } });
515	    if (byIp) return { ok: false, error: "This code has already been claimed from your connection." };
516	  }
517	  if (opts.maxRedemptions !== null) {
518	    const c = await db.coupon.findUnique({ where: { id: opts.couponId }, select: { timesRedeemed: true, active: true } });
519	    if (!c || !c.active || c.timesRedeemed >= opts.maxRedemptions) return { ok: false, error: "This code has reached its redemption limit." };
520	  }
521	  return { ok: true };
522	}
