537	  // Everything below bills off THESE three, never off `quote.chargeCents` /
538	  // `promo` directly: when a sold price is present it is the whole truth about
539	  // what this order costs and what rate it was sold at.
540	  const chargeCents = sold?.chargeCents ?? quote.chargeCents;
541	  const promoPercent = sold?.promoPercent ?? promo.discountPercent;
542	  const promoName = sold?.promoName || promo.name;
