846	          // to zero even if the admin retunes `annual_discount_percent` in between
847	          // (Finding 2). Ignored for non-annual terms by `termDiscountPct`; a free admin
848	          // grant never prorates, so its value is inert. `quote.annualPct` is the very
849	          // rate `regularPlanCents`/`chargeCents` above were priced at.
850	          annualDiscountPct: quote.annualPct,
851	          // The plan-portion cash actually collected for this term, net of promo AND
852	          // coupon, EXCLUDING recurring add-ons — the authoritative refund basis (see
853	          // Server.refundableTermCents). `regularPlanCents` is the full term list;
854	          // subtract the promo credit ONLY if the claim held (a lost wallet claim paid
855	          // full, `soldFull`), and always subtract the coupon (it reduced cash but never
856	          // `termPromoPercent`). Clamped ≥ 0. A free admin grant collected nothing, so 0.
857	          refundableTermCents: freeRequested
858	            ? 0
859	            : Math.max(
860	                0,
861	                quote.regularPlanCents - (soldFull ? 0 : promoCreditCents) - quote.couponDiscountCents,
862	              ),
863	          // Persisted BEFORE the PROVISION job runs, so the worker clones the VM
864	          // and resizes scsi0 straight to plan.diskGB + extraDiskGB — the server is
865	          // born at its full size, with no separate expansion job.
866	          extraDiskGB,
867	          wantsDedicatedIp: !!intent.dedicatedIp,
868	          isFree: freeRequested,
869	          expiresAt: freeRequested ? null : addMonths(new Date(), term.months),
870	        } as Prisma.ServerUncheckedCreateInput,
871	      });
872	      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
873	      // Anchor the redemption to the created server so the renewal worker can flip
874	      // `renewed` when this customer bills their second term, and stamp the true
875	      // first-term charge. Same tx, so it commits (or rolls back) with the order.
876	      if (promoClaimId) await setPromoOrderRef(tx, promoClaimId, s.id, debitCents);
877	      return s;
878	    });
879	  } catch (e) {
880	    if (e instanceof InsufficientBalanceError) throw new OrderError("Insufficient balance.");
881	    throw e;
882	  }
883	
884	  await db.auditLog.create({
885	    data: {
886	      userId: user.id,
887	      action: "server.order",
888	      detail: `${server.id} image=${os.slug} plan=${plan.slug} term=${term.months}mo extraDisk=${extraDiskGB}GB free=${freeRequested}`,
889	    },
890	  });
891	  if (!freeRequested) {
892	    try {
893	      await maybeRewardReferral(user.id);
894	    } catch {
895	      /* non-fatal */
896	    }
897	    // Soft monthly-budget alert (Finding 3): fire once when this charge tips spend
898	    // over the customer's budget. Best-effort — never fails an order.
899	    await maybeAlertBudget(user.id);
900	    // KOL/Agency partner commission: if this customer is attached to a partner,
901	    // accrue commission on the PAID order invoice now (idempotent; the background
902	    // sweep would otherwise catch it within minutes). Best-effort by design.
903	    await accrueRecentCommissionsForCustomer(user.id);
904	  }
905	  return server.id;
906	}
