/**
 * Pricing + renewal-period math for the recurring add-on products
 * (business email subscriptions and block-storage volumes).
 *
 * Deliberately PURE: no `db`, no I/O, no side effects — everything here is a
 * plain function over plain values so the renewal policy can be unit-tested
 * without a database. The worker sweep (`worker/product-renewals.ts`) owns all
 * the reads/writes and asks this module *what* should happen.
 *
 * Policy shape mirrors `worker/billing.ts` (VPS/domains) so customers see one
 * consistent billing behaviour across every product:
 *   warn before expiry -> expire -> grace period -> enforce (suspend / detach)
 */

import { addMonths, termPriceCents } from "./billing-terms";

export const DAY_MS = 86_400_000;

/** Read a positive integer from the environment, falling back on a default. */
export function envInt(name: string, fallback: number): number {
  const raw = process.env[name];
  const n = Number(raw);
  return raw !== undefined && Number.isFinite(n) && n >= 0 ? n : fallback;
}

/**
 * Days after expiry during which the product keeps working while we retry the
 * charge and nag the customer. Shares NXEON_GRACE_DAYS with worker/billing.ts
 * so every product on the account expires on the same schedule.
 */
export const PRODUCT_GRACE_DAYS = envInt("NXEON_GRACE_DAYS", 3);

/** How many days before expiry we send the "renews soon" heads-up. */
export const PRODUCT_WARN_DAYS = envInt("NXEON_PRODUCT_WARN_DAYS", 3);

/**
 * Days after the grace window before an unpaid, detached volume is considered
 * abandoned and may be reclaimed by staff. Nothing in this codebase deletes
 * customer data automatically — this only drives the wording of the warning so
 * the customer knows the disk will not sit there unpaid forever.
 */
export const PRODUCT_RECLAIM_DAYS = envInt("NXEON_TERMINATE_DAYS", 10);

/** Notification dedupe window (matches the 4-day window used by billing.ts). */
export const NOTIFY_DEDUPE_DAYS = envInt("NXEON_PRODUCT_NOTIFY_DEDUPE_DAYS", 4);

/** Volumes are priced per month and always renew monthly. */
export const VOLUME_TERM_MONTHS = 1;

/** "$12.34" — the money format used across notifications and wallet lines. */
export function money(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`;
}

/** Date as "YYYY-MM-DD" for human-readable deadlines in notifications. */
export function ymd(d: Date): string {
  return d.toISOString().slice(0, 10);
}

/** Amount charged to renew an email subscription for one plan term. */
export function emailRenewalCents(plan: { priceCents: number }): number {
  return Math.max(0, Math.round(plan.priceCents));
}

/** Plan term in whole months, clamped to >= 1 so a bad row can't stall renewal. */
export function emailRenewalMonths(plan: { termMonths?: number | null }): number {
  const m = Math.round(Number(plan.termMonths ?? 1));
  return Number.isFinite(m) && m >= 1 ? m : 1;
}

/**
 * The billing term (whole months) a subscription/account was SOLD on, clamped
 * to >= 1 so a bad row can never stall its renewal. This is the CUSTOMER'S chosen
 * term (1 = monthly, 12 = annual), stored on the subscription/account row — not
 * the plan's period. A pre-existing row (no column) defaults to 1 = monthly.
 */
export function subscriptionTermMonths(row: { termMonths?: number | null }): number {
  const m = Math.round(Number(row.termMonths ?? 1));
  return Number.isFinite(m) && m >= 1 ? m : 1;
}

/**
 * The MONTHLY base price of an email plan. Every seeded email plan is priced
 * monthly (`termMonths: 1`), so this is normally just `priceCents`; dividing by the
 * plan's own term keeps it correct if an admin ever configures a multi-month plan.
 * The per-term charge is then `termPriceCents(base, subscriptionTerm, annualPct)`.
 */
export function emailMonthlyBaseCents(plan: { priceCents: number; termMonths?: number | null }): number {
  return Math.max(0, Math.round(plan.priceCents / emailRenewalMonths(plan)));
}

/**
 * The annual discount FROZEN on an add-on row (HostingAccount / EmailSubscription)
 * at sale, or null when the row predates the column / was sold monthly. Mirrors
 * `frozenAnnualDiscountPct` in lib/annual-discount.ts: the cast contains the
 * stale-client gap (the symlinked prod Prisma client's types predate these columns
 * until it is regenerated at deploy — identical at runtime then). A frozen 0 is
 * honoured (nullish, not falsy); only a genuinely absent value falls back to live.
 */
export function frozenProductAnnualPct(row: unknown): number | null {
  const v = (row as { annualDiscountPct?: number | null } | null | undefined)?.annualDiscountPct;
  return typeof v === "number" && Number.isFinite(v) ? v : null;
}

/**
 * What one renewal costs for a term-billed add-on product (Shared Hosting or
 * Business Email): `monthlyCents × months × (1 − annualDiscount)` — the SAME
 * formula VPS/game/NxCloud use (`termPriceCents`). `annualDiscountPct` is the rate
 * FROZEN on the row at sale, falling back to the live setting (passed by the sweep)
 * when the row predates the column or was sold monthly. So an annual account renews
 * annually at the rate it was sold — displayed === charged === renewed. For a
 * monthly term this is exactly the monthly price, so no existing row moves.
 */
export function productTermRenewalCents(
  monthlyCents: number,
  months: number,
  annualDiscountPct: number,
): number {
  return Math.max(0, termPriceCents(monthlyCents, months, annualDiscountPct));
}

/** Amount charged to renew a volume for one month. */
export function volumeRenewalCents(volume: { priceCents: number }): number {
  return Math.max(0, Math.round(volume.priceCents));
}

/**
 * The expiry a renewal should advance to.
 *
 * The base is `max(currentExpiry, now)`, so an item that has been expired for
 * months is brought forward to one full term from *today* with a single charge
 * rather than being back-billed for every missed period. This also guarantees
 * the new expiry is always strictly in the future, which is what makes the
 * sweep idempotent (the "due" query only selects `expiresAt < now`).
 */
export function nextExpiry(
  currentExpiry: Date | null | undefined,
  now: Date,
  months: number
): Date {
  const base = new Date(
    Math.max(currentExpiry ? currentExpiry.getTime() : now.getTime(), now.getTime())
  );
  return addMonths(base, Math.max(1, Math.round(months)));
}

/** Instant the grace period ends for an item that expired at `expiresAt`. */
export function graceEndsAt(expiresAt: Date, graceDays: number = PRODUCT_GRACE_DAYS): Date {
  return new Date(expiresAt.getTime() + graceDays * DAY_MS);
}

/** True once the grace period after `expiresAt` has fully elapsed. */
export function isPastGrace(
  expiresAt: Date,
  now: Date,
  graceDays: number = PRODUCT_GRACE_DAYS
): boolean {
  return now.getTime() > graceEndsAt(expiresAt, graceDays).getTime();
}

/** Date after which an unpaid volume may be reclaimed (messaging only). */
export function reclaimAt(
  expiresAt: Date,
  graceDays: number = PRODUCT_GRACE_DAYS,
  reclaimDays: number = PRODUCT_RECLAIM_DAYS
): Date {
  return new Date(expiresAt.getTime() + (graceDays + reclaimDays) * DAY_MS);
}

/** Lower bound for "have we already sent this notification recently?" lookups. */
export function dedupeSince(now: Date, days: number = NOTIFY_DEDUPE_DAYS): Date {
  return new Date(now.getTime() - days * DAY_MS);
}

/** True when the item has passed its paid-through date and owes a renewal. */
export function isDueForRenewal(expiresAt: Date | null | undefined, now: Date): boolean {
  return !!expiresAt && expiresAt.getTime() < now.getTime();
}

/** True when the item expires inside the pre-expiry warning window. */
export function isRenewingSoon(
  expiresAt: Date | null | undefined,
  now: Date,
  warnDays: number = PRODUCT_WARN_DAYS
): boolean {
  if (!expiresAt) return false;
  const t = expiresAt.getTime();
  return t > now.getTime() && t < now.getTime() + warnDays * DAY_MS;
}

/** Whether the wallet covers a renewal (free items always "afford" themselves). */
export function canAfford(balanceCents: number, priceCents: number): boolean {
  return priceCents <= 0 || balanceCents >= priceCents;
}

/**
 * What the sweep should do with an item that is past its expiry date.
 *  - `renew`   charge the wallet and push `expiresAt` forward
 *  - `grace`   still inside the grace window: leave it running, nag the owner
 *  - `enforce` grace elapsed and unpaid: suspend (email) / detach (volume)
 */
export type RenewalAction = "renew" | "grace" | "enforce";

export function renewalDecision(opts: {
  expiresAt: Date;
  now: Date;
  autoRenew: boolean;
  balanceCents: number;
  priceCents: number;
  graceDays?: number;
}): RenewalAction {
  const { expiresAt, now, autoRenew, balanceCents, priceCents } = opts;
  if (autoRenew && canAfford(balanceCents, priceCents)) return "renew";
  if (isPastGrace(expiresAt, now, opts.graceDays)) return "enforce";
  return "grace";
}

/**
 * Whether a pre-expiry warning is warranted: only bother the customer when the
 * renewal would actually fail today (auto-renew off, or wallet too low).
 */
export function needsUpcomingWarning(opts: {
  autoRenew: boolean;
  balanceCents: number;
  priceCents: number;
}): boolean {
  return !(opts.autoRenew && canAfford(opts.balanceCents, opts.priceCents));
}

// Imported from the PURE module, never from ./stripe-cards: this file is reached
// by the deploy wizard, a client component, and stripe-cards pulls the Stripe SDK
// and nodemailer — which breaks the browser build with "Can't resolve 'fs'".
import { renewalCharge, type PricedServer, type RenewalPrices } from "./renewal-charge";

/**
 * What "Renew now" costs and how long it buys — for the BUTTON that quotes it.
 *
 * This is a presentation wrapper over `renewalCharge` (lib/stripe-cards.ts) and
 * deliberately owns no arithmetic of its own. It exists only to add the duration
 * phrasing the UI needs.
 *
 * WHY IT IS A WRAPPER RATHER THAN A FORMULA.
 *
 * The original incident: the button read `Renew now (+30 days, $8.99)` and
 * charged **$97.09**, moving the expiry twelve months — the label hardcoded
 * "+30 days" and the plan's MONTHLY price while `renewNow` charged a full term.
 * The fix was to compute the quote and the charge in one place.
 *
 * The second incident, hours later and in this very file: that shared place was
 * written as fresh arithmetic over `plan.priceCents`, which silently ignored
 * `gamePlan`. A game server carries BOTH a base `planId` and a `gamePlanId`, and
 * it is sold at the game plan's flat price — `minecraft-mm8w85` was sold at
 * $4.99 while its base Starter plan is $8.99. So the new shared quote would have
 * charged a game-server owner **80% more than they agreed to** the moment they
 * pressed Renew now. `renewalCharge` had handled this correctly all along, and
 * the automatic renewal sweep in `worker/billing.ts` already used it.
 *
 * The lesson is the one this codebase keeps relearning: the danger was never a
 * wrong formula, it was a SECOND formula. So there is exactly one, it lives in
 * `renewalCharge`, and everything that quotes or charges a renewal goes through
 * it — the worker sweep, the card path, this button, and the server page.
 */
export type RenewalQuote = {
  /** Total charged, in cents — tax-INCLUSIVE (net + tax) when a rate was passed. */
  totalCents: number;
  /** The pre-tax subtotal; invoice line items sum to this. */
  netCents: number;
  /** VAT/GST added on top of the net (0 when no rate passed). */
  taxCents: number;
  /** The rate (%) the tax was computed at. */
  taxRatePercent: number;
  /** Months the expiry advances by. */
  months: number;
  /** Human label for the duration, e.g. "12 months" / "1 month". */
  durationLabel: string;
  /** What the customer is buying ("Starter VPS", or the game plan's name). */
  label: string;
};

export function renewalQuote(
  server: PricedServer,
  prices: RenewalPrices,
): RenewalQuote {
  const charge = renewalCharge(server, prices);
  return {
    totalCents: charge.totalCents,
    netCents: charge.netCents,
    taxCents: charge.taxCents,
    taxRatePercent: charge.taxRatePercent,
    months: charge.months,
    durationLabel: charge.months === 1 ? "1 month" : `${charge.months} months`,
    label: charge.label,
  };
}

import { vpsTerm, vpsTermPriceCents, termPriceCents } from "./billing-terms";
import { extraDiskCentsAt } from "./extra-disk";
import { type BackupTier, backupTierMonthlyCents } from "./backup-tiers";

/**
 * What one renewal costs — the SINGLE definition, used by every path that quotes
 * or charges one: the automatic sweep in worker/billing.ts, the saved-card path,
 * the "Renew now" button, the server page and the deploy wizard's term cards.
 *
 * WHY IT LIVES IN ITS OWN FILE. It used to sit in lib/stripe-cards.ts, which
 * imports the Stripe SDK and (transitively) nodemailer. The moment a CLIENT
 * component — the deploy wizard — needed the renewal price, that import chain
 * dragged `nodemailer/lib/dkim` into the browser bundle and the build failed with
 * "Can't resolve 'fs'". The pricing rule is pure arithmetic and has no business
 * carrying a mail transport with it, so it lives here with only the two tiny
 * modules it genuinely needs. lib/stripe-cards.ts re-exports it, so no server-side
 * caller had to change.
 *
 * The rule this file exists to enforce: there is ONE renewal formula. Two
 * incidents in one day came from a second copy — first a button that hardcoded
 * "+30 days" and the monthly price while the action charged a full term ($8.99
 * shown, $97.09 taken), then the shared quote written to fix it, which computed
 * from `plan.priceCents` and so ignored `gamePlan` and would have billed a $4.99
 * game server at its $8.99 base plan. Do not add a second formula.
 */
export type RenewalCharge = {
  months: number;
  /**
   * The amount to CHARGE / display — tax-INCLUSIVE (net + tax). When no
   * `taxRatePercent` is supplied (the default), tax is 0 and this equals `netCents`,
   * so every existing caller is unchanged. Because display and charge both read this
   * one field, `displayed === charged === renewed` holds by construction.
   */
  totalCents: number;
  /** The pre-tax subtotal (plan + IP + disk + backup). Invoice line items sum to this. */
  netCents: number;
  /** The VAT/GST added on top of `netCents` (Finding 1); 0 when no rate was passed. */
  taxCents: number;
  /** The rate (%) `taxCents` was computed at, recorded on the invoice. */
  taxRatePercent: number;
  /** The extra-root-disk portion, which gets its own invoice line. */
  extraDiskCents: number;
  extraDiskMonthlyCents: number;
  /** The paid backup-tier portion (Plus retention), which gets its own invoice line. */
  backupCents: number;
  backupMonthlyCents: number;
  /** Human label for the invoice / receipt ("Nebula VPS" or the game plan name). */
  label: string;
};

export type PricedServer = {
  termMonths: number;
  extraDiskGB: number;
  plan: { name: string; priceCents: number };
  gamePlan: { name: string; priceCents: number; termMonths: number } | null;
  dedicatedIp: unknown | null;
  /** Paid backup retention tier. A full Server row supplies it; synthetic callers must pass it. */
  backupTier: BackupTier;
  /**
   * The ANNUAL discount FROZEN on this server at sale (`Server.annualDiscountPct`),
   * or null on a legacy/monthly/flat row. OPTIONAL so the many synthetic
   * `PricedServer` display/quote objects keep compiling; a full Server row supplies
   * it automatically. When present it WINS over the live `prices.annualDiscountPct`,
   * so an annual VPS / NxCloud / game server renews at exactly the rate it was
   * SOLD at even if the admin retunes the setting afterwards; null falls back to
   * the live rate, which for every non-annual term is identical maths.
   */
  annualDiscountPct?: number | null;
};

/**
 * The admin-priced inputs a renewal is charged against. Every field is REQUIRED
 * deliberately, mirroring how the codebase guards renewal pricing everywhere else
 * (`termPromoPercent` is likewise required in lib/proration.ts): a call site that
 * builds this object cannot silently forget one and fall back to a stale default.
 */
export type RenewalPrices = {
  ipMonthlyCents: number;
  extraDiskPerGbCents: number;
  backupPlusCents: number;
  /**
   * The admin-configured ANNUAL discount (percent), resolved from the
   * `annual_discount_percent` setting via `annualDiscountPct()`.
   *
   * REQUIRED — not optional. A 12-month server renews at
   * `vpsTermPriceCents(price, 12, annualDiscountPct)`; if a call site could OMIT
   * this it would silently price annual at the shipped default (10%) while the
   * owner had set, say, 20% — the rate the customer was shown and charged at order.
   * Required turns that into a compile error at every one of the ~8 places that
   * build this object, so the annual setting cannot be forgotten on any renewal
   * path and `displayed === charged === renewed` holds.
   */
  annualDiscountPct: number;
  /**
   * OPTIONAL destination VAT/GST rate (percent) for the customer who owns this
   * server, resolved from their billing country (lib/tax.ts taxContextForUser).
   * Omitted / 0 => no tax added and `totalCents === netCents`, so every call site
   * that does not opt in is byte-for-byte unchanged. A charge site passes the
   * OWNER's rate so the wallet debit, the card leg and the invoice all agree; a
   * display of the owner's own renewal passes the SAME rate so the figure shown
   * equals the figure taken.
   */
  taxRatePercent?: number;
};

export function renewalCharge(
  server: PricedServer,
  prices: RenewalPrices,
): RenewalCharge {
  const isGame = !!server.gamePlan;
  // The term to renew — the customer's chosen `Server.termMonths` (1 = monthly,
  // 12 = annual). A game term is now a per-order choice (Monthly / Annual) just like
  // a VPS, so it rides the Server row, not the plan.
  //
  // VPS/NxCloud terms are always one of the 4 standard `VPS_TERMS`, so we normalise
  // through `vpsTerm`. A GAME server, however, may historically carry ANY term the
  // plan was configured with (a pre-existing game server was created with
  // `termMonths = gamePlan.termMonths`, which the admin can set 1..36). We therefore
  // read the game term back RAW (clamped >= 1) rather than through `vpsTerm`, whose
  // fallback would collapse a non-standard legacy value (say 3) to monthly and
  // change that server's renewal cadence. For the seeded games (all `termMonths: 1`)
  // and any new Monthly/Annual order this is identical to the standard path.
  const months = isGame ? Math.max(1, Math.round(server.termMonths)) : vpsTerm(server.termMonths).months;
  // The annual discount to price the term at: the rate FROZEN on the server at sale,
  // falling back to the live setting for legacy/monthly rows. Both halves resolve
  // the same number, so an annual sub renews at the sold rate.
  const annualPct = server.annualDiscountPct ?? prices.annualDiscountPct;
  // Extra root disk is billed EVERY cycle at the current per-GB price. Game plans
  // are a flat all-in price and never carry the add-on lines.
  const extraDiskMonthlyCents = isGame ? 0 : extraDiskCentsAt(server.extraDiskGB, prices.extraDiskPerGbCents);
  const extraDiskCents = extraDiskMonthlyCents * months;
  // Paid backup retention (Plus) rides alongside extra disk: billed every cycle at
  // the current admin price, and — like every add-on line — NOT carried by a game
  // plan (renewalCharge's game branch is flat all-in, so game servers are never
  // sold a paid backup tier; see lib/backup-upgrade.ts's game guard).
  const backupMonthlyCents = isGame ? 0 : backupTierMonthlyCents(server.backupTier, prices.backupPlusCents);
  const backupCents = backupMonthlyCents * months;
  // A game plan's `priceCents` is its MONTHLY base (every seed is `termMonths: 1`).
  // Divide by the plan's own term so an admin plan configured as, say, a 3-month
  // bundle still yields a per-month rate; then price the customer's chosen term
  // through the SAME formula VPS uses. For a monthly game server this is exactly
  // `priceCents`; an ANNUAL game server renews at 12× that, less the annual discount.
  const gameMonthlyCents = isGame
    ? Math.round(server.gamePlan!.priceCents / Math.max(1, server.gamePlan!.termMonths))
    : 0;
  // LEGACY GUARD. Game servers sold BEFORE terms existed carry no frozen annual rate
  // (`annualDiscountPct == null`) and always renewed at the plan's FLAT `priceCents`,
  // with no term discount ever applied. Preserve that exactly so no pre-existing game
  // server's renewal moves — only servers sold through the new term-aware flow (which
  // always stamps a frozen `annualDiscountPct`) are priced with `termPriceCents`.
  //
  // GUARD ON isGame FIRST. This value is only USED in the isGame branch below, but a
  // bare ternary evaluates it for EVERY server — and a VPS `PricedServer` (e.g. the one
  // the deploy wizard builds, `gamePlan: null`, no `annualDiscountPct`) then hits the
  // `annualDiscountPct == null` arm and dereferences `server.gamePlan!.priceCents` on a
  // null, crashing the whole deploy page with "Cannot read properties of null". Compute
  // 0 for non-game so the null is never touched.
  const gameTotalCents = !isGame
    ? 0
    : server.annualDiscountPct == null
      ? server.gamePlan!.priceCents
      : termPriceCents(gameMonthlyCents, months, annualPct);
  const netCents = isGame
    ? gameTotalCents
    : vpsTermPriceCents(server.plan.priceCents, months, annualPct) +
      // Bill the IP surcharge only when the server ACTUALLY holds a dedicated IP,
      // not off the intent flag — a NAT-fallback server must never be charged for
      // an IP it never received.
      (server.dedicatedIp ? prices.ipMonthlyCents * months : 0) +
      extraDiskCents +
      backupCents;
  // VAT/GST on the pre-tax subtotal. Default rate 0 keeps `totalCents === netCents`
  // for every caller that does not pass the owner's rate (Finding 1).
  const taxRatePercent =
    Number.isFinite(prices.taxRatePercent) && (prices.taxRatePercent ?? 0) > 0 ? prices.taxRatePercent! : 0;
  const taxCents = Math.round((netCents * taxRatePercent) / 100);
  return {
    months,
    netCents,
    taxCents,
    taxRatePercent,
    totalCents: netCents + taxCents,
    extraDiskCents,
    extraDiskMonthlyCents,
    backupCents,
    backupMonthlyCents,
    label: isGame ? server.gamePlan!.name : `${server.plan.name} VPS`,
  };
}

  const sold = orderPriceOf({
    chargeCents: promoPriceCents(vpsTermPriceCents(899, 12), SOLD_BASIS),
    promo: SOLD_BASIS,
  });
  assert.deepEqual(sold, { chargeCents: 6796, promoPercent: 30, promoName: "Summer Sale" });
  // Stripe metadata values are strings, and this one is written and read back on
  // opposite sides of a browser redirect.
  const roundTripped = parseOrderPrice(JSON.stringify(sold));
  assert.deepEqual(roundTripped, sold);
  // It also has to fit: Stripe caps a metadata value at 500 characters and the
  // writer slices to 490. A price that can be truncated is a price that can be lost.
  assert.ok(JSON.stringify(sold).length < 200, "the stamped price is nowhere near the metadata cap");
});

test("the settled total does not move when the promo rotates under it", () => {
  const sold = orderPriceOf({
    chargeCents: promoPriceCents(vpsTermPriceCents(899, 12), SOLD_BASIS),
    promo: SOLD_BASIS,
  });
  // What placeOrder now bills: `sold.chargeCents ?? quote.chargeCents`. The stamped
  // value is a constant — no date, no promo lookup, nothing that a browser redirect
  // taking an hour can change.
  const settled = parseOrderPrice(JSON.stringify(sold))!.chargeCents;
  assert.equal(settled, 6796);
  assert.notEqual(settled, promoPriceCents(vpsTermPriceCents(899, 12), REQUOTE_BASIS));
  // And the rate travels with it, because Server.termPromoPercent records the rate
  // the term was SOLD at. Stamping today's 15% against a 30% price would hand every
  // later proration the wrong basis (see lib/proration.ts).
  assert.equal(parseOrderPrice(JSON.stringify(sold))!.promoPercent, 30);
});

test("a malformed stamped price is refused outright rather than half-believed", () => {
  // The fallback is a fresh quote — the old behaviour. That is only safe if a
  // partially-valid price can never be accepted: a total without its rate would be
  // charged at one price and prorated against another.
  for (const bad of [
    undefined,
    null,
    "",
    "not json",
    "{}",
    '{"chargeCents":"6796","promoPercent":30}',
    '{"chargeCents":6796.5,"promoPercent":30}',
    '{"chargeCents":-1,"promoPercent":30}',
    '{"chargeCents":6796}',
    '{"chargeCents":6796,"promoPercent":101}',
    '{"chargeCents":6796,"promoPercent":-1}',
  ]) {
    assert.equal(parseOrderPrice(bad), null, `must reject ${JSON.stringify(bad)}`);
  }
  // A price with no promo name is still a valid price — the name is ledger text.
  assert.deepEqual(parseOrderPrice('{"chargeCents":6796,"promoPercent":0}'), {
    chargeCents: 6796,
    promoPercent: 0,
    promoName: "",
  });
});

test("the order path stamps the price before the card is charged and settles it after", () => {
  const stripe = code("../lib/stripe.ts");
  const order = code("../lib/order.ts");
  const fulfil = code("../lib/fulfil-checkout.ts");
  // Was `nxeonOrderPrice: JSON.stringify(price)`. It now goes through
  // `packMetadata`, which REFUSES an oversized payload instead of slicing it —
  // see test/checkout-metadata.test.ts for why a sliced payload silently became a
  // wallet top-up with no server. The property pinned here is unchanged and
  // stronger: the total is stamped, and now it cannot be stamped half-written.
  assert.match(stripe, /nxeonOrderPrice: packMetadata\("Order price", price\)/, "the total is stamped on the session");
  assert.match(
    stripe,
    /sold \?\? orderPriceOf\(await orderQuote\(intent\)\)/,
    "the price is fixed at session creation — before any money moves",
  );
  assert.match(
    stripe,
    /if \(price\.chargeCents < amountCents\)/,
    "a card leg larger than the order total is refused, not discovered at confirm",
  );
  assert.match(stripe, /sold: parseOrderPrice\(session\.metadata\?\.nxeonOrderPrice\)/, "and read back on confirm");
  assert.match(fulfil, /placeOrder\(user, order\.intent, order\.sold\)/, "confirm settles the stamped price");
  assert.match(
    order,
    /const chargeCents = sold\?\.chargeCents \?\? quote\.chargeCents/,
    "placeOrder bills the sold price when there is one",
  );
  assert.match(
    order,
    /termPromoPercent: freeRequested \? 100 : promoPercent/,
    "and records the rate it was SOLD at, not the promo running now",
  );
});

