export function PlanForm({ plan }: { plan?: Plan }) {
  const [state, action, pending] = useActionState(adminSavePlan, {});
  return (
    <form action={action} className="grid grid-cols-2 gap-3 sm:grid-cols-4">
      {plan?.id && <input type="hidden" name="id" value={plan.id} />}
      {state?.error && (
        <div className="col-span-full rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
          {state.error}
        </div>
      )}
      <div>
        <label className="label">Slug</label>
        <input className="input" name="slug" defaultValue={plan?.slug} required />
      </div>
      <div>
        <label className="label">Name</label>
        <input className="input" name="name" defaultValue={plan?.name} required />
      </div>
      <div>
        <label className="label">vCPU</label>
        <input className="input" name="cpuCores" type="number" defaultValue={plan?.cpuCores ?? 1} required />
      </div>
      <div>
        <label className="label">RAM (MB)</label>
        <input className="input" name="ramMB" type="number" defaultValue={plan?.ramMB ?? 1024} required />
      </div>
      <div>
        <label className="label">Disk (GB)</label>
        <input className="input" name="diskGB" type="number" defaultValue={plan?.diskGB ?? 15} required />
      </div>
      <div>
        <label className="label">Bandwidth (TB)</label>
        <input className="input" name="bandwidthTB" type="number" step="0.1" defaultValue={plan?.bandwidthTB ?? 1} required />
      </div>
      <div>
        <label className="label">Price (cents/mo)</label>
        <input className="input" name="priceCents" type="number" defaultValue={plan?.priceCents ?? 500} required />
      </div>
      <div className="flex items-end gap-3">
        <label className="flex items-center gap-2 pb-2 text-sm">
          <input type="checkbox" name="active" defaultChecked={plan?.active ?? true} /> Active
        </label>
        <button className="btn-primary" disabled={pending}>
          {pending ? "Saving…" : "Save"}
        </button>
      </div>
    </form>
  );
}

